6	const uint RADIX = 256;
7	const uint WORKGROUP_SIZE = 512;
8	const uint PARTITION_DIVISION = 8;
9	const uint PARTITION_SIZE = PARTITION_DIVISION * WORKGROUP_SIZE;
10	const uint MAX_SUBGROUP_SIZE = 128;
11	
12	layout(local_size_x = WORKGROUP_SIZE) in;
13	
14	layout(push_constant) uniform PushConstants {
15	    int pass;
16	} pc;
