24	};
25	
26	layout(set = 0, binding = 2, std430) buffer PartitionHistogram {
27	    uint partitionHistogram[];
28	};
29	
30	shared uint reduction;
31	shared uint intermediate[MAX_SUBGROUP_SIZE];
32	
33	void main() {
34	    uint elementCount = elementCounts[0];
35	
36	    uint laneIndex = gl_SubgroupInvocationID;
37	    uint laneCount = gl_SubgroupSize;
38	    uint waveIndex = gl_LocalInvocationIndex / laneCount;
39	    uint waveCount = WORKGROUP_SIZE / laneCount;
40	    uint index = waveIndex * laneCount + laneIndex;
41	
42	    uint radix = gl_WorkGroupID.x;
43	    uint partitionCount = (elementCount + PARTITION_SIZE - 1) / PARTITION_SIZE;
44	
45	    if (index == 0) {
46	        reduction = 0;
47	    }
48	    barrier();
49	
50	    for (uint i = 0; WORKGROUP_SIZE * i < partitionCount; ++i) {
51	        uint partitionIndex = WORKGROUP_SIZE * i + index;
52	        uint value = partitionIndex < partitionCount ? partitionHistogram[RADIX * partitionIndex + radix] : 0;
53	        uint excl = subgroupExclusiveAdd(value) + reduction;
54	        uint sum = subgroupAdd(value);
55	
56	        if (subgroupElect()) {
57	            intermediate[waveIndex] = sum;
58	        }
59	        barrier();
60	
61	        if (index < waveCount) {
62	            uint intermediateExcl = subgroupExclusiveAdd(intermediate[index]);
63	            uint intermediateSum = subgroupAdd(intermediate[index]);
64	            intermediate[index] = intermediateExcl;
65	
66	            if (index == 0) {
67	                reduction += intermediateSum;
68	            }
69	        }
70	        barrier();
71	
72	        if (partitionIndex < partitionCount) {
73	            excl += intermediate[waveIndex];
74	            partitionHistogram[RADIX * partitionIndex + radix] = excl;
75	        }
76	        barrier();
77	    }
78	
79	    if (radix == 0) {
80	        if (index < RADIX) {
81	            uint value = globalHistogram[RADIX * uint(pc.pass) + index];
82	            uint excl = subgroupExclusiveAdd(value);
83	            uint sum = subgroupAdd(value);
84	
85	            if (subgroupElect()) {
86	                intermediate[waveIndex] = sum;
87	            }
88	            barrier();
89	
90	            if (index < RADIX / laneCount) {
91	                uint intermediateExcl = subgroupExclusiveAdd(intermediate[index]);
92	                intermediate[index] = intermediateExcl;
