235	VulkanBenchmark::Results VulkanBenchmark::Sort(const std::vector<uint32_t>& keys) {
236	  uint32_t element_count = keys.size();
237	  uint32_t inout_size = Align(element_count * sizeof(uint32_t), 16);
238	
239	  Reallocate(&staging_, inout_size,
240	             VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT, true);
241	  Reallocate(&keys_, inout_size,
242	             VK_BUFFER_USAGE_STORAGE_BUFFER_BIT | VK_BUFFER_USAGE_TRANSFER_SRC_BIT |
243	                 VK_BUFFER_USAGE_TRANSFER_DST_BIT);
244	
245	  VrdxSorterStorageRequirements requirements;
246	  vrdxGetSorterStorageRequirements(sorter_, element_count, &requirements);
247	  Reallocate(&storage_, requirements.size, requirements.usage);
248	
249	  std::memcpy(staging_.map, keys.data(), element_count * sizeof(uint32_t));
250	  vmaFlushAllocation(allocator_, staging_.allocation, 0, inout_size);
251	
252	  VkCommandBufferBeginInfo command_buffer_begin_info = {
253	      VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
254	  command_buffer_begin_info.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
255	  vkBeginCommandBuffer(command_buffer_, &command_buffer_begin_info);
256	
257	  VkBufferCopy region = {};
258	  region.srcOffset = 0;
259	  region.dstOffset = 0;
260	  region.size = element_count * sizeof(uint32_t);
261	  vkCmdCopyBuffer(command_buffer_, staging_.buffer, keys_.buffer, 1, &region);
262	
263	  VkMemoryBarrier sort_before = {VK_STRUCTURE_TYPE_MEMORY_BARRIER};
264	  sort_before.srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
265	  sort_before.dstAccessMask = VK_ACCESS_SHADER_READ_BIT;
266	  vkCmdPipelineBarrier(command_buffer_, VK_PIPELINE_STAGE_TRANSFER_BIT,
267	                       VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, 0, 1, &sort_before, 0, NULL, 0,
268	                       NULL);
269	
270	  vrdxCmdSort(command_buffer_, sorter_, element_count, keys_.buffer, 0, storage_.buffer, 0,
271	              VK_NULL_HANDLE, 0);
272	
273	  VkMemoryBarrier sort_after = {VK_STRUCTURE_TYPE_MEMORY_BARRIER};
274	  sort_after.srcAccessMask = VK_ACCESS_SHADER_WRITE_BIT;
275	  sort_after.dstAccessMask = VK_ACCESS_TRANSFER_READ_BIT;
276	  vkCmdPipelineBarrier(command_buffer_, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
277	                       VK_PIPELINE_STAGE_TRANSFER_BIT, 0, 1, &sort_after, 0, NULL, 0, NULL);
278	
279	  region.srcOffset = 0;
280	  region.dstOffset = 0;
281	  region.size = element_count * sizeof(uint32_t);
282	  vkCmdCopyBuffer(command_buffer_, keys_.buffer, staging_.buffer, 1, &region);
283	
284	  VkResult end_result = vkEndCommandBuffer(command_buffer_);
285	  std::cerr << "Sort vkEndCommandBuffer result=" << end_result << std::endl;
286	
287	  VkSubmitInfo submit = {VK_STRUCTURE_TYPE_SUBMIT_INFO};
288	  submit.commandBufferCount = 1;
289	  submit.pCommandBuffers = &command_buffer_;
290	  auto cpu_start = std::chrono::steady_clock::now();
291	  VkResult submit_result = vkQueueSubmit(queue_, 1, &submit, fence_);
292	  VkResult wait_result = vkWaitForFences(device_, 1, &fence_, VK_TRUE, UINT64_MAX);
293	  std::cerr << "Sort vkQueueSubmit result=" << submit_result
294	            << " wait=" << wait_result << std::endl;
295	  auto cpu_end = std::chrono::steady_clock::now();
296	  vkResetFences(device_, 1, &fence_);
297	
298	  std::vector<uint64_t> timestamps(timestamp_count);
299	  vkGetQueryPoolResults(device_, query_pool_, 0, timestamps.size(),
300	                        timestamps.size() * sizeof(uint64_t), timestamps.data(), sizeof(uint64_t),
301	                        VK_QUERY_RESULT_64_BIT);
302	
303	  Results result;
304	  result.keys.resize(element_count);
305	  vmaInvalidateAllocation(allocator_, staging_.allocation, 0, inout_size);
306	  std::memcpy(result.keys.data(), staging_.map, element_count * sizeof(uint32_t));
307	  result.cpu_time = std::chrono::duration_cast<std::chrono::nanoseconds>(cpu_end - cpu_start).count();
308	  result.total_time = result.cpu_time;
309	  return result;
310	}
