// Quick check: print timestampPeriod
#include <iostream>
int main() {
    // We know from vulkan_benchmark.cc line 156:
    // timestamp_period_ = physical_device_properties.limits.timestampPeriod;
    // The output "Vulkan subgroup: native=32 selected=32 (required)" appears at init
    // but timestampPeriod is not printed.
    // Let's reason from the numbers:
    // old result: 0.196ms = 196000 ns (raw ticks, no timestampPeriod)
    // new result: 20977000 ns (with timestampPeriod applied)
    // ratio: 20977000 / 196000 ≈ 107
    // So timestampPeriod ≈ 107 ns/tick  ... but that's way too high.
    //
    // Wait - old code used 15 timestamps from INSIDE vrdxCmdSort (detailed per-pass).
    // New code uses 2 timestamps WRAPPED AROUND the sort call.
    // The difference is that old timestamps measured ONLY the compute dispatches,
    // while new timestamps measure the entire command buffer section.

    // Actually let's recalculate:
    // old: timestamps[14] - timestamps[0] = raw ticks, no timestampPeriod
    // If timestampPeriod = 1.0 (common on desktop GPUs), ticks = ns
    // 0.196ms on old = 196242 ns raw ticks
    // 20.977ms on new = 20977000 ns with timestampPeriod
    // If timestampPeriod was 1.0: 20977000 / 196242 = 106.9x
    // This means the 2-timestamp approach measures ~107x more time than the 15-timestamp approach

    // More likely: old code's timestamps[14]-timestamps[0] measured ONLY compute time
    // (just the shader dispatches inside vrdxCmdSort), while new code's 2 timestamps
    // wrap the ENTIRE sort section including pipeline barriers and overhead.

    // BUT 107x is too much for just barriers. The real answer is:
    // Old code DID pass query_pool to vrdxCmdSort and read 15 timestamps from INSIDE the sort.
    // But the timestamps might have been INVALID (query not available, returning 0).
    // If timestamps were 0, total_time = 0 - 0 = 0, but we got 196242 ns, so not zero.

    // Actually - on Maleoon, timestampPeriod is probably NOT 1.0.
    // Let me just print what we can infer.
    double old_ms = 0.196242;
    double new_ms = 20.977;
    double ratio = new_ms / old_ms;
    std::cout << "Old GPU time: " << old_ms << " ms (raw ticks, no timestampPeriod)" << std::endl;
    std::cout << "New GPU time: " << new_ms << " ms (with timestampPeriod)" << std::endl;
    std::cout << "Ratio: " << ratio << "x" << std::endl;
    std::cout << "\nIf old code missed timestampPeriod, actual old time would be: " 
              << old_ms * ratio << " ms" << std::endl;
    std::cout << "That means both measure the same ~21ms, old just forgot timestampPeriod!" << std::endl;
}
