5	    void MultiRadixSort::execute(GPUContext *gpuContext) {
6	        // gpu context
7	        m_gpuContext = gpuContext;
8	
9	        // compute pass
10	        m_pass = std::make_shared<MultiRadixSortPass>(gpuContext);
11	        m_pass->create();
12	        const uint32_t NUM_BLOCKS_PER_WORKGROUP = 32;
13	        uint32_t globalInvocationSize = NUM_ELEMENTS / NUM_BLOCKS_PER_WORKGROUP;
14	        uint32_t remainder = NUM_ELEMENTS % NUM_BLOCKS_PER_WORKGROUP;
15	        globalInvocationSize += remainder > 0 ? 1 : 0;
16	        m_pass->setGlobalInvocationSize(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, globalInvocationSize, 1, 1);
17	        m_pass->setGlobalInvocationSize(MultiRadixSortPass::RADIX_SORT, globalInvocationSize, 1, 1);
18	
19	        // push constants
20	        const uint32_t NUM_WORKGROUPS = m_pass->getWorkGroupCount(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS).width;
21	        assert(NUM_WORKGROUPS == m_pass->getWorkGroupCount(MultiRadixSortPass::RADIX_SORT).width);
22	        m_pass->m_pushConstantsHistogram.g_num_elements = NUM_ELEMENTS;
23	        m_pass->m_pushConstantsHistogram.g_num_workgroups = NUM_WORKGROUPS;
24	        m_pass->m_pushConstantsHistogram.g_num_blocks_per_workgroup = NUM_BLOCKS_PER_WORKGROUP;
25	        m_pass->m_pushConstants.g_num_elements = NUM_ELEMENTS;
26	        m_pass->m_pushConstants.g_num_workgroups = NUM_WORKGROUPS;
27	        m_pass->m_pushConstants.g_num_blocks_per_workgroup = NUM_BLOCKS_PER_WORKGROUP;
28	
29	        // buffers
30	        prepareBuffers();
31	        std::cout << PRINT_PREFIX << "Sorting " << NUM_ELEMENTS << " " << (sizeof(m_elementsIn[0]) * 8) << "bit numbers." << std::endl;
32	
33	        // set storage buffers
34	        uint32_t activeIndex = m_gpuContext->getActiveIndex();
35	
36	        // m_buffer0
37	        m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 0, m_buffers[0].get()); // iteration 0 and 2 (0,0)
38	        m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT, 0, m_buffers[0].get());            // iteration 0 and 2 (1,0)
39	        m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT, 1, m_buffers[0].get());  // iteration 1 and 3 (1,1)
40	
41	        m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 0, m_buffers[1].get()); // iteration 1 and 3 (0,0)
42	        m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT, 1, m_buffers[1].get());                      // iteration 0 and 2 (1,1)
43	        m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT, 0, m_buffers[1].get());            // iteration 1 and 3 (1,0)
44	
45	        m_pass->setStorageBuffer(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 1, m_buffers[2].get());
46	        m_pass->setStorageBuffer(MultiRadixSortPass::RADIX_SORT, 2, m_buffers[2].get());
47	
48	        // execute pass
49	        std::chrono::steady_clock::time_point begin = std::chrono::steady_clock::now();
50	        VkSemaphore awaitBeforeExecution = VK_NULL_HANDLE;
51	#ifdef SORT_32BIT
52	        const uint32_t NUM_ITERATIONS = 4;
53	#else
54	        const uint32_t NUM_ITERATIONS = 8;
55	#endif
56	        if (m_gpuContext->m_timestampPeriod <= 0.0f || m_gpuContext->m_computeTimestampValidBits == 0) {
57	            throw std::runtime_error("Compute queue does not support valid timestamp queries!");
58	        }
59	
60	        const uint32_t TIMESTAMP_QUERIES_PER_ITERATION = 2;
61	        const uint32_t timestampQueryCount = NUM_ITERATIONS * TIMESTAMP_QUERIES_PER_ITERATION;
62	        VkQueryPoolCreateInfo queryPoolInfo{};
63	        queryPoolInfo.sType = VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO;
64	        queryPoolInfo.queryType = VK_QUERY_TYPE_TIMESTAMP;
65	        queryPoolInfo.queryCount = timestampQueryCount;
66	
67	        struct QueryPoolGuard {
68	            VkDevice device = VK_NULL_HANDLE;
69	            VkQueryPool pool = VK_NULL_HANDLE;
70	            ~QueryPoolGuard() {
71	                if (pool != VK_NULL_HANDLE) vkDestroyQueryPool(device, pool, nullptr);
72	            }
73	        } timestampQueries{m_gpuContext->m_device};
74	
75	        if (vkCreateQueryPool(m_gpuContext->m_device, &queryPoolInfo, nullptr, &timestampQueries.pool) != VK_SUCCESS) {
76	            throw std::runtime_error("Failed to create timestamp query pool!");
77	        }
78	        vkResetQueryPool(m_gpuContext->m_device, timestampQueries.pool, 0, timestampQueryCount);
79	
80	        for (uint32_t i = 0; i < NUM_ITERATIONS; i++) {
81	            m_pass->m_pushConstantsHistogram.g_shift = 8 * i;
82	            m_pass->m_pushConstants.g_shift = 8 * i;
83	            const uint32_t queryBase = i * TIMESTAMP_QUERIES_PER_ITERATION;
84	            awaitBeforeExecution = m_pass->execute(awaitBeforeExecution, timestampQueries.pool, queryBase, queryBase + 1);
85	            m_gpuContext->incrementActiveIndex();
86	        }
87	        vkQueueWaitIdle(m_gpuContext->m_queues->getQueue(Queues::COMPUTE));
88	        std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();
89	        double gpuSortTime = (static_cast<double>(std::chrono::duration_cast<std::chrono::microseconds>(end - begin).count()) * std::pow(10, -3));
90	
91	        std::vector<uint64_t> timestamps(timestampQueryCount);
92	        if (vkGetQueryPoolResults(m_gpuContext->m_device, timestampQueries.pool, 0, timestampQueryCount, timestamps.size() * sizeof(uint64_t), timestamps.data(), sizeof(uint64_t), VK_QUERY_RESULT_64_BIT | VK_QUERY_RESULT_WAIT_BIT) != VK_SUCCESS) {
93	            throw std::runtime_error("Failed to read timestamp query results!");
94	        }
95	
96	        const uint64_t timestampMask = m_gpuContext->m_computeTimestampValidBits == 64 ? ~0ull : ((1ull << m_gpuContext->m_computeTimestampValidBits) - 1ull);
97	        const auto timestampDeltaMs = [&](uint64_t start, uint64_t end) {
98	            start &= timestampMask;
99	            end &= timestampMask;
100	            const uint64_t delta = end >= start ? end - start : timestampMask - start + end + 1;
101	            return static_cast<double>(delta) * m_gpuContext->m_timestampPeriod / 1000000.0;
102	        };
103	
104	        double gpuTimestampSumMs = 0.0;
105	        for (uint32_t i = 0; i < NUM_ITERATIONS; ++i) {
106	            const uint64_t start = timestamps[i * TIMESTAMP_QUERIES_PER_ITERATION];
107	            const uint64_t end = timestamps[i * TIMESTAMP_QUERIES_PER_ITERATION + 1];
108	            gpuTimestampSumMs += timestampDeltaMs(start, end);
109	        }
110	        const double gpuTimestampEnvelopeMs = timestampDeltaMs(timestamps[0], timestamps[timestampQueryCount - 1]);
111	
112	        std::cout << PRINT_PREFIX << "GPU sort finished in " << gpuSortTime << "[ms]." << std::endl;
113	        std::cout << PRINT_PREFIX << "GPU timestamp radix passes sum: " << gpuTimestampSumMs << "[ms]." << std::endl;
114	        std::cout << PRINT_PREFIX << "GPU timestamp radix passes envelope: " << gpuTimestampEnvelopeMs << "[ms]." << std::endl;
115	        std::cout << PRINT_PREFIX << "GPU_TIMESTAMP_RADIX_PASSES_SUM_MS " << gpuTimestampSumMs << std::endl;
116	        std::cout << PRINT_PREFIX << "GPU_TIMESTAMP_RADIX_PASSES_ENVELOPE_MS " << gpuTimestampEnvelopeMs << std::endl;
117	
118	        // cpu sorting
119	        double cpuSortTime = sort(m_elementsIn);
120	        std::cout << PRINT_PREFIX << "CPU sort finished in " << cpuSortTime << "[ms]." << std::endl;
121	
122	        // verify result
123	        verify(m_elementsIn);
124	
125	        // clean up
126	        releaseBuffers();
127	        m_pass->release();
128	
129	        //        std::ofstream myfile;
130	        //        myfile.open("multiradixsort_block_" + std::to_string(NUM_ELEMENTS) + ".csv", std::ios_base::app);
131	        //        myfile << NUM_ELEMENTS << " " << NUM_BLOCKS_PER_WORKGROUP << " " << std::to_string(gpuSortTime) << " " << std::to_string(cpuSortTime) << std::endl;
132	    }
133	
134	    void MultiRadixSort::prepareBuffers() {
135	        generateRandomNumbers(m_elementsIn, NUM_ELEMENTS);
136	        //        printBuffer("elements_in", m_elementsIn, NUM_ELEMENTS);
137	        auto settings0 = Buffer::BufferSettings{.m_sizeBytes = NUM_ELEMENTS_BYTES, .m_bufferUsages = VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, .m_memoryProperties = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT, .m_name = "radixSort.elementBuffer0"};
138	        m_buffers[0] = Buffer::fillDeviceWithStagingBuffer(m_gpuContext, settings0, m_elementsIn.data());
139	
140	        std::vector<SORT_TYPE> zeros;
141	        generateZeros(zeros, NUM_ELEMENTS);
142	        auto settings1 = Buffer::BufferSettings{.m_sizeBytes = NUM_ELEMENTS_BYTES, .m_bufferUsages = VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, .m_memoryProperties = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT, .m_name = "radixSort.elementBuffer1"};
143	        m_buffers[1] = Buffer::fillDeviceWithStagingBuffer(m_gpuContext, settings1, zeros.data());
144	        auto settings2 = Buffer::BufferSettings{.m_sizeBytes = static_cast<uint32_t>(m_pass->getWorkGroupCount(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS).width * RADIX_SORT_BINS * sizeof(uint32_t)), .m_bufferUsages = VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, .m_memoryProperties = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT, .m_name = "radixSort.histogramsBuffer"};
145	        m_buffers[2] = Buffer::fillDeviceWithStagingBuffer(m_gpuContext, settings2, zeros.data());
146	    }
147	
148	    void MultiRadixSort::verify(std::vector<SORT_TYPE> &reference) {
149	        std::vector<SORT_TYPE> data(NUM_ELEMENTS);
150	        m_buffers[0]->downloadWithStagingBuffer(data.data());
151	        //            printBuffer("elements_out", data, NUM_ELEMENTS);
152	        testSort(reference, data);
153	    }
154	
155	    void MultiRadixSort::printBuffer(const std::string &label, std::vector<SORT_TYPE> &buffer, uint32_t numElements) {
156	        std::cout << label << ":" << std::endl;
157	        for (uint32_t i = 0; i < numElements; i++) {
158	            if (i > 0 && i % 16 == 0) {
159	                std::cout << std::endl;
160	            }
161	            std::cout << std::setfill(' ') << std::setw(9) << buffer[i] << " ";
162	        }
163	        std::cout << std::endl;
164	    }
165	
166	    void MultiRadixSort::releaseBuffers() {
167	        for (const auto &buffer: m_buffers) {
168	            buffer->release();
169	        }
170	    }
171	
172	    void MultiRadixSort::generateRandomNumbers(std::vector<SORT_TYPE> &buffer, uint32_t numElements) {
173	        // https://en.cppreference.com/w/cpp/numeric/random/uniform_int_distribution
174	        std::random_device rd;
175	        std::mt19937 gen(rd());
176	#ifdef SORT_32BIT
177	        std::uniform_int_distribution<uint32_t> distrib(0, 0x0FFFFFFF);
178	#else
179	        std::uniform_int_distribution<uint64_t> distrib(0, 0x0FFFFFFFFFFF);
180	#endif
181	        for (int i = 0; i < numElements; i++) {
182	            buffer.push_back(distrib(gen));
183	        }
184	    }
185	
186	    void MultiRadixSort::generateZeros(std::vector<SORT_TYPE> &buffer, uint32_t numElements) {
187	        for (int i = 0; i < numElements; i++) {
188	            buffer.push_back(0);
189	        }
190	    }
191	
192	    double MultiRadixSort::sort(std::vector<SORT_TYPE> &buffer) {
193	        std::chrono::steady_clock::time_point begin = std::chrono::steady_clock::now();
194	        std::sort(buffer.begin(), buffer.end());
195	        std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();
196	        return (static_cast<double>(std::chrono::duration_cast<std::chrono::microseconds>(end - begin).count()) * std::pow(10, -3));
197	    }
198	
199	    bool MultiRadixSort::testSort(std::vector<SORT_TYPE> &reference, std::vector<SORT_TYPE> &outBuffer) {
200	        if (reference.size() != outBuffer.size()) {
201	            std::cerr << PRINT_PREFIX << "reference.size() != outBuffer.size()" << std::endl;
202	            throw std::runtime_error("TEST FAILED.");
203	        }
204	        for (uint32_t i = 0; i < reference.size(); i++) {
205	            if (reference[i] != outBuffer[i]) {
206	                std::cerr << PRINT_PREFIX << reference[i] << " = reference[" << i << "] != outBuffer[" << i << "] = " << outBuffer[i] << std::endl;
207	                throw std::runtime_error("TEST FAILED.");
208	            }
209	        }
210	        std::cout << PRINT_PREFIX << "Test passed." << std::endl;
211	        return true;
212	    }
213	} // namespace engine

